query:
-- Verify TX governor
SELECT state_code, dem_candidate, rep_candidate, status FROM governor_races WHERE state_code = 'TX';

-- Check AR House races
SELECT state_code, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code IN ('AR', 'MS') ORDER BY state_code, CAST(district AS UNSIGNED);

